function generateParenthesis(n) {
  const result = [];
  const path = [];
  const build = (open, close) => {            // how many '(' and ')' are used so far
    if (path.length === 2 * n) {
      result.push(path.join(""));
      return;
    }
    if (open < n) {                           // a '(' is allowed while some are left
      path.push("(");
      build(open + 1, close);
      path.pop();
    }
    if (close < open) {                       // a ')' only if it closes something
      path.push(")");
      build(open, close + 1);
      path.pop();
    }
  };
  build(0, 0);
  return result;
}

List<String> generateParenthesis(int n) {
    List<String> result = new ArrayList<>();
    build(new StringBuilder(), 0, 0, n, result);
    return result;
}

void build(StringBuilder path, int open, int close, int n, List<String> result) {
    if (path.length() == 2 * n) {
        result.add(path.toString());
        return;
    }
    if (open < n) {                              // a '(' is allowed while some are left
        path.append('(');
        build(path, open + 1, close, n, result);
        path.deleteCharAt(path.length() - 1);
    }
    if (close < open) {                          // a ')' only if it closes something
        path.append(')');
        build(path, open, close + 1, n, result);
        path.deleteCharAt(path.length() - 1);
    }
}

void build(string& path, int open, int close, int n, vector<string>& result) {
    if ((int)path.size() == 2 * n) {
        result.push_back(path);
        return;
    }
    if (open < n) {                              // a '(' is allowed while some are left
        path.push_back('(');
        build(path, open + 1, close, n, result);
        path.pop_back();
    }
    if (close < open) {                          // a ')' only if it closes something
        path.push_back(')');
        build(path, open, close + 1, n, result);
        path.pop_back();
    }
}

